import { useEffect, useMemo, useState } from "react";
import {
  Activity, AlertCircle, ArrowLeft, ArrowRight, ArrowUpRight, AtSign, Ban, Bell,
  CalendarClock, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp,
  ClipboardList, Clock3, Copy, FileText, Filter, Flag, GitBranch, Hash, Inbox,
  Layers3, ListChecks, LockKeyhole, Mail, MessageCircle, MoreHorizontal, PanelRight,
  Plus, Search, Send, Settings2, ShieldCheck, Sparkles, Tag, Users, UserRound,
  Workflow, X, Zap
} from "lucide-react";
import "./clubhouse-crm.css";
import { Modal, PageHead } from "./_shared/SharedChrome";
import { ContactsView, OpportunitiesView } from "./_shared/PipelineViews";
import { WorkflowsView } from "./_shared/WorkflowsView";
import { TagsView } from "./_shared/TagsAudienceView";
import { CorporateReview, ExceptionsView, Overview, ReportsView, SettingsView, TemplatesView } from "./_shared/WorkspaceViews";
import { CATALOG, classForStatus, DEALS, DEFAULT_FLOW, EXCEPTIONS, families, initials, LOCATIONS, NAV, sampleThreads, STAGES, TEMPLATE_TEXT } from "./_shared/demoData";
import type { FlowNode, NodeKind, Thread, View } from "./_shared/demoData";

 
export function CRMWorkbench() {
  const [view, setView] = useState<View>(() => {
    const requested = new URLSearchParams(window.location.search).get("view")?.toLowerCase();
    return NAV.find(item => item.name.toLowerCase() === requested)?.name ?? "Conversations";
  });
  const [location, setLocation] = useState(LOCATIONS[0]);
  const [role, setRole] = useState("Owner · demo");
  const [threads, setThreads] = useState(sampleThreads);
  const [activeThreadId, setActiveThreadId] = useState(1);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [queue, setQueue] = useState("Needs reply");
  const [threadSearch, setThreadSearch] = useState("");
  const [familyRecords, setFamilyRecords] = useState(families);
  const [selectedFamily, setSelectedFamily] = useState(families[0]);
  const [messageMode, setMessageMode] = useState<"Reply" | "Internal note">("Reply");
  const [draft, setDraft] = useState("");
  const [savedDraft, setSavedDraft] = useState("");
  const [selectedTemplate, setSelectedTemplate] = useState("Evaluation follow-up");
  const [showContext, setShowContext] = useState(true);
  const [mobileThread, setMobileThread] = useState(() => new URLSearchParams(window.location.search).get("thread") === "1");
  const [modal, setModal] = useState("");
  const [toast, setToast] = useState("");
  const [contactSearch, setContactSearch] = useState("");
  const [contactStatus, setContactStatus] = useState("All families");
  const [contactTags, setContactTags] = useState<string[]>([]);
  const [tagLibrary, setTagLibrary] = useState(["Evaluation booked", "Interested · camps", "Member", "New lead", "Trial", "Two athletes", "Opt-out review"]);
  const [archivedTags, setArchivedTags] = useState<string[]>([]);
  const [entityTags, setEntityTags] = useState<Record<number, { family: string[]; adult: string[]; athlete: string[] }>>({});
  const [tagEntity, setTagEntity] = useState<"family" | "adult" | "athlete">("family");
  const [audienceRule, setAudienceRule] = useState("has");
  const [audienceTag, setAudienceTag] = useState("Interested · camps");
  const [audienceLogic, setAudienceLogic] = useState("AND");
  const [audienceLocation, setAudienceLocation] = useState(LOCATIONS[0].split(" · ")[0]);
  const [audienceMembership, setAudienceMembership] = useState("Any membership");
  const [audienceSelectedTags, setAudienceSelectedTags] = useState(["Interested · camps", "Member"]);
  const [audiencePreview, setAudiencePreview] = useState<{included:any[];excluded:any[]}>({included:[],excluded:[]});
  const [stageNames, setStageNames] = useState(STAGES);
  const [stageMigrations, setStageMigrations] = useState<Record<string,string>>({});
  const [dealRecords, setDealRecords] = useState(DEALS);
  const [selectedDeal, setSelectedDeal] = useState(DEALS[0]);
  const [dealStage, setDealStage] = useState("");
  const [flowTab, setFlowTab] = useState("Editor");
  const [flowNodes, setFlowNodes] = useState(DEFAULT_FLOW);
  const [selectedNode, setSelectedNode] = useState(2);
  const [simulationRecipientId, setSimulationRecipientId] = useState(1);
  const [workflowStatusByLocation, setWorkflowStatusByLocation] = useState<Record<string,{paused:boolean;scope:string}>>({});
  const [workflowName, setWorkflowName] = useState("Evaluation lead · first 7 days");
  const [workflowReentry, setWorkflowReentry] = useState("Once per unique event");
  const [workflowRecurrence, setWorkflowRecurrence] = useState("No recurrence");
  const [workflowRelativeTiming, setWorkflowRelativeTiming] = useState("Appointment-relative · recalculates on move");
  const [workflowSharing, setWorkflowSharing] = useState<Record<string, string>>({});
  const [templateBody, setTemplateBody] = useState(TEMPLATE_TEXT);
  const [templateNote, setTemplateNote] = useState("");
  const [aiState, setAiState] = useState("Available · refreshed 9:36 AM");
  const [scheduled, setScheduled] = useState(false);
  const [teammateComposing, setTeammateComposing] = useState(true);
  const [settingsTab, setSettingsTab] = useState("Channels");
  const [bulkSelection, setBulkSelection] = useState<string[]>([]);
  const [bulkTag, setBulkTag] = useState("Interested · camps");
  const [exception, setException] = useState(0);
  const [roleModal, setRoleModal] = useState(false);
  const [smsConnections, setSmsConnections] = useState<Record<string, boolean>>({});
  const [gmailConnections, setGmailConnections] = useState<Record<string, boolean>>({});
  const [heldQueuedByLocation, setHeldQueuedByLocation] = useState<Record<string, boolean>>({});
  const workflowPaused=workflowStatusByLocation[location]?.paused??false;
  const pauseScope=workflowStatusByLocation[location]?.scope??"new entries";

  const allowedLocationThreads = threads.filter(t => t.location === location && (!role.startsWith("Instructor") || t.assigned === "Devon") && !role.startsWith("Corporate"));
  const queueCounts = [
    allowedLocationThreads.filter(t=>t.unread||t.assigned==="Unassigned"||t.consent==="Review").length,
    allowedLocationThreads.filter(t=>t.assigned===(role.startsWith("Instructor")?"Devon":"You")).length,
    allowedLocationThreads.length,
    allowedLocationThreads.filter(t=>t.messages.some(m=>m.kind==="scheduled")).length,
    allowedLocationThreads.filter(t=>t.consent!=="Eligible").length
  ];
  const currentThread = allowedLocationThreads.find(t => t.id === activeThreadId) ?? allowedLocationThreads[0] ?? {
    id: -1, adult: "No selected conversation", athlete: "No linked athlete", initials: "—", preview: "",
    time: "", location, assigned: "Unassigned", consent: "Review" as const, phone: "",
    tags: [], messages: []
  };
  const visibleThreads = useMemo(() => threads.filter(t => t.location === location)
    .filter(t => queue === "All conversations" ? true : queue === "Needs reply" ? (t.unread || t.assigned === "Unassigned" || t.consent === "Review") : queue === "Assigned to me" ? t.assigned === (role.startsWith("Instructor")?"Devon":"You") : queue === "Opt-out / review" ? (t.consent !== "Eligible") : queue === "Scheduled" ? t.messages.some(m => m.kind === "scheduled") : true)
    .filter(t => `${t.adult} ${t.athlete} ${t.preview}`.toLowerCase().includes(threadSearch.toLowerCase()))
    .filter(t => !role.startsWith("Instructor") || t.assigned === "Devon")
    .filter(() => !role.startsWith("Corporate")), [threads, location, queue, threadSearch, role]);
  const visibleFamilies = familyRecords.filter(f => f.location === location.replace(" · Austin", ""))
    .filter(f => contactStatus === "All families" || f.status === contactStatus)
    .filter(f => `${f.adult} ${f.athletes}`.toLowerCase().includes(contactSearch.toLowerCase()))
    .filter(f => !contactTags.length || contactTags.every(t => f.tags.includes(t)))
    .filter(f => !role.startsWith("Instructor") || allowedLocationThreads.some(t => t.adult === f.adult))
    .filter(() => !role.startsWith("Corporate"));
  const bulkSelected=bulkSelection.length>0;
  const bulkTargets=familyRecords.filter(f=>f.location===location.split(" · ")[0]&&bulkSelection.includes(f.adult));
  const locationFamilies=familyRecords.filter(f=>f.location===location.split(" · ")[0]).filter(f=>!role.startsWith("Instructor")||allowedLocationThreads.some(t=>t.adult===f.adult)).filter(()=>!role.startsWith("Corporate"));
  const visibleDeals = dealRecords.filter(d => familyRecords.some(f => f.adult === d.family && f.location === location.split(" · ")[0]))
    .filter(() => !role.startsWith("Instructor") && !role.startsWith("Corporate"));
  const currentThreadDeal=visibleDeals.find(d=>d.family===currentThread.adult);
  const duplicateSuggestions=location.startsWith("North Loop")&&!role.startsWith("Instructor")?[["Evan Brooks","Kai Brooks","shared phone · verify adult authority"],["Jordan Alvarez","Sofia Alvarez","shared household · two linked athletes"]]:[];
  const isInstructor = role.startsWith("Instructor");
  const isCorporate = role.startsWith("Corporate");
  const queuedSampleCount=location.startsWith("North Loop")?2:location.startsWith("Cedar Park")?1:0;
  const eligibleToSend = currentThread.id > 0 && currentThread.consent === "Eligible" && !isInstructor && !isCorporate;
  const teammateReviewing=currentThread.id>0&&currentThread.assigned==="You"&&teammateComposing;
  const simulationThread = allowedLocationThreads.find(t=>t.id===simulationRecipientId) ?? currentThread;
  const workflowDiff = [
    ...flowNodes.filter((node:FlowNode)=>!DEFAULT_FLOW.some(base=>base.id===node.id)).map((node:FlowNode)=>`+ ${node.kind}: ${node.title}`),
    ...flowNodes.filter((node:FlowNode)=>DEFAULT_FLOW.some(base=>base.id===node.id&&(`${base.kind}|${base.title}|${base.detail}|${base.timing||""}`!==`${node.kind}|${node.title}|${node.detail}|${node.timing||""}`))).map((node:FlowNode)=>{const base=DEFAULT_FLOW.find(item=>item.id===node.id)!;return `~ ${node.id}: ${base.title} → ${node.title}${base.timing!==node.timing?` · timing: ${base.timing||"unset"} → ${node.timing||"unset"}`:""}`;}),
    ...DEFAULT_FLOW.filter(base=>!flowNodes.some((node:FlowNode)=>node.id===base.id)).map(base=>`− ${base.kind}: ${base.title}`)
  ];
  const workflowValidation = [
    ...(!flowNodes.some(n=>n.kind==="trigger")?["Add a trigger node."]:[]),
    ...(!flowNodes.some(n=>n.kind==="goal exit")?["Add an explicit goal or exit node."]:[]),
    ...(flowNodes.some(n=>n.kind==="SMS")&&!smsConnections[location]?["Location SMS sender is not configured; simulated publish is blocked."]:[]),
    ...(flowNodes.some(n=>n.kind==="SMS")&&!allowedLocationThreads.some(t=>t.consent==="Eligible")?["No eligible adult recipient exists in this location for the SMS path."]:[])
  ];

  function flash(text: string) { setToast(text); window.setTimeout(() => setToast(""), 2500); }
  function go(next: View) { setView(next); setMobileThread(false); window.history.replaceState({}, "", next === "Workflows" ? "?view=workflows" : "?view=conversations"); }
  function changeLocation(next: string) {
    setLocation(next);
    setAudienceLocation(next.split(" · ")[0]);
    setTemplateBody(TEMPLATE_TEXT.replaceAll("North Loop",next.split(" · ")[0]));
    const first = threads.find(t => t.location === next && (!role.startsWith("Instructor") || t.assigned === "Devon"));
    setActiveThreadId(first?.id ?? -1);
    setSelectedFamily(familyRecords.find(f => f.location === next.split(" · ")[0]) ?? { adult: "No selected family", initials: "—", athletes: "", location: next.split(" · ")[0], membership: "Unavailable", tags: [], last: "", status: "Review" });
    const localDeals = dealRecords.filter(d=>familyRecords.some(f=>f.adult===d.family&&f.location===next.split(" · ")[0]));
    setSelectedDeal(localDeals[0] ?? {name:"No opportunity at this location",family:"",stage:"",value:"",owner:"",due:"",tags:[]});
    setSimulationRecipientId(threads.find(t=>t.location===next&&(!role.startsWith("Instructor")||t.assigned==="Devon"))?.id??-1);
    setDraft(""); setSavedDraft(""); setModal(""); setMobileThread(false); setMobileMenuOpen(false); setBulkSelection([]);
  }
  function changeRole(next: string) {
    setRole(next);
    const first = threads.find(t => t.location === location && (!next.startsWith("Instructor") || t.assigned === "Devon") && !next.startsWith("Corporate"));
    setActiveThreadId(first?.id ?? -1);
    setSimulationRecipientId(first?.id ?? -1);
    setDraft(""); setSavedDraft(""); setMobileThread(false); setMobileMenuOpen(false); setModal(""); setBulkSelection([]);
  }
  function chooseThread(id: number) {
    setActiveThreadId(id); setMobileThread(true); setDraft(""); setSavedDraft("");
    setThreads(prev => prev.map(t => t.id === id ? { ...t, unread: false } : t));
  }
  function insertTemplate() { setDraft(TEMPLATE_TEXT.replace("North Loop",location.split(" · ")[0]).replace("{{guardian_first}}", currentThread.adult.split(" ")[0]).replace("{{athlete_first}}", currentThread.athlete.split(" ")[0])); flash("Approved sample template inserted; review before sending."); }
  function sendMessage(schedule = false) {
    if (!draft.trim()) { flash("Add a draft before continuing."); return; }
    if (!eligibleToSend) { flash("Blocked: review recipient, role and SMS consent. Nothing was sent."); return; }
    if (teammateReviewing) { setModal("stale"); return; }
    const item = { from: `You · ${location.split(" · ")[0]}`, text: draft, time: schedule ? "Scheduled · tomorrow 9:00 AM" : "Simulated · just now", kind: schedule ? "scheduled" as const : undefined };
    setThreads(prev => prev.map(t => t.id === activeThreadId ? { ...t, messages: [...t.messages, item], preview: schedule ? "Scheduled message · tomorrow" : draft, time: "now" } : t));
    setDraft(""); setScheduled(schedule); flash(schedule ? "Preview scheduled locally. No message will be delivered." : "Simulated send recorded in this local prototype. No message was delivered.");
  }
  function addInternalNote() {
    if (!draft.trim()) return;
    const note = { from: "You · private note", text: draft, time: "Simulated · just now", kind: "internal" as const };
    setThreads(prev => prev.map(t => t.id === activeThreadId ? { ...t, messages: [...t.messages, note], preview: `Private note · ${draft}`, time: "now" } : t));
    setDraft(""); flash("Private note added to this synthetic example thread.");
  }
  function assignThread(owner: string) {
    setThreads(prev => prev.map(t => t.id === activeThreadId ? { ...t, assigned: owner } : t));
    flash(`Ownership changed to ${owner} in this demo only.`);
  }
  function addFlowNode(kind: NodeKind) {
    const copy: FlowNode = { id: Date.now(), kind, title: kind === "wait" ? "Wait 1 day" : kind === "tag-add" ? "Add Interested · camps" : kind === "tag-remove" ? "Remove Trial tag" : kind === "SMS" ? "Send approved SMS template" : kind === "goal exit" ? "Goal reached · exit" : kind === "internal action" ? "Create staff task" : kind === "reply timeout" ? "Wait for guardian reply" : kind === "condition" ? "Check guardian eligibility" : "New trigger", detail: `${kind} · select to configure`, timing: "At next eligible local time" };
    setFlowNodes(prev => [...prev, copy]); setSelectedNode(copy.id); flash(`${kind} node added to the editable sample flow.`);
  }
  function addTagToFamily(name: string) { if (!contactTags.includes(name)) setContactTags(prev => [...prev, name]); flash(`${name} filter applied to the visible synthetic family list.`); }
  function renameTag(oldName:string,newName:string) {
    if (!newName.trim() || newName===oldName || tagLibrary.includes(newName.trim())) return;
    const next=newName.trim();
    setTagLibrary(prev=>prev.map(tag=>tag===oldName?next:tag));
    setContactTags(prev=>prev.map(tag=>tag===oldName?next:tag));
    setAudienceSelectedTags(prev=>prev.map(tag=>tag===oldName?next:tag));
    setFamilyRecords(prev=>prev.map(f=>({...f,tags:f.tags.map(tag=>tag===oldName?next:tag)})));
    setThreads(prev=>prev.map(t=>({...t,tags:t.tags.map(tag=>tag===oldName?next:tag)})));
    flash(`Renamed ${oldName}; linked family, thread and audience references were updated.`);
  }
  function archiveTag(tag:string) {
    setTagLibrary(prev=>prev.filter(item=>item!==tag));
    setArchivedTags(prev=>prev.includes(tag)?prev:[...prev,tag]);
    flash(`${tag} archived. Existing record references are preserved for review.`);
  }
  function restoreTag(tag:string) {
    setArchivedTags(prev=>prev.filter(item=>item!==tag));
    setTagLibrary(prev=>prev.includes(tag)?prev:[...prev,tag]);
    flash(`${tag} restored to the active tag library.`);
  }
  function closeModal() { setModal(""); }
  function setWorkflowPaused(paused:boolean) { setWorkflowStatusByLocation(prev=>({...prev,[location]:{paused,scope:pauseScope}})); }
  function setPauseScope(scope:string) { setWorkflowStatusByLocation(prev=>({...prev,[location]:{paused:prev[location]?.paused??false,scope}})); }
  useEffect(() => {
    if (!modal) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") closeModal(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [modal]);

  const switcher = <div className="top-actions">
    <span className="demo-pill">SIMULATED · RESET ON REFRESH</span>
    <label className="eyebrow mobile-only" htmlFor="location-switch-mobile">Location</label>
    <select id="location-switch-mobile" className="role-select mobile-only" value={location} onChange={e=>changeLocation(e.target.value)} aria-label="Switch demo location on this device">{LOCATIONS.map(l=><option key={l}>{l}</option>)}</select>
    <label className="eyebrow" htmlFor="role-switch">Role</label>
    <select id="role-switch" className="role-select" value={role} onChange={e => { changeRole(e.target.value); setRoleModal(true); }} aria-label="Demo role">
      {["Owner · demo", "GM · proposal", "Instructor · assigned only", "Corporate · proposal"].map(r => <option key={r}>{r}</option>)}
    </select>
    <button className="icon-btn" aria-label="Exception state review" onClick={() => go("Exception review")}><Bell size={15}/></button>
  </div>;

  return <div className="ch-crm">
    <div className="app-shell">
      <aside className="sidebar">
        <div className="brandlock"><div className="brandmark">C</div><div><div className="brandword">CLUBHOUSE</div><div className="brandtag">INFINITE HITTING · CRM</div></div></div>
        <div className="location-box"><div className="eyebrow">Working location</div><select className="location-select" value={location} onChange={e => changeLocation(e.target.value)} aria-label="Switch demo location">{LOCATIONS.map(l => <option key={l}>{l}</option>)}</select></div>
        <div className="nav-label">Workspace</div>
        <nav className="nav-list" aria-label="CRM sections">{NAV.map(({ name, icon: Icon, count: staticCount }) => {const count=name==="Conversations"?String(allowedLocationThreads.length):staticCount;return <button key={name} className={`nav-item ${view === name ? "active" : ""}`} onClick={() => go(name)} aria-current={view === name ? "page" : undefined}><Icon size={15}/><span>{name}</span>{count && <span className="nav-count">{count}</span>}</button>;})}</nav>
        <div className="sidebar-foot">
          <div className="demo-stamp">Demo workspace<br/><strong>All family records are synthetic.</strong><br/>Changes reset on refresh.</div>
          <div className="staff-row"><div className="avatar">JL</div><div><div className="staff-name">Jamie Lee</div><div className="staff-role">Owner · demo identity</div></div><ChevronDown size={13} style={{marginLeft:"auto"}}/></div>
        </div>
      </aside>
      <main className="main-area">
        <header className="topbar"><div className="crumb">Clubhouse <ChevronRight size={12} style={{verticalAlign:"middle"}}/> <strong>{view}</strong></div>{switcher}</header>
        <div className={`content view-fade ${view === "Conversations" ? "conversation-page" : ""}`}>
          {isCorporate ? <CorporateReview location={location} sharing={workflowSharing[location]||"pending"} setSharing={(v:string)=>setWorkflowSharing(prev=>({...prev,[location]:v}))} flash={flash}/> : <>
          {view === "Overview" && <Overview go={go} flash={flash} location={location} role={role}/>}
          {view === "Conversations" && <section>
            <div className="page-heading"><div><h1>Conversations</h1><div className="subhead">One adult recipient, one location sender. Keep the family context close.</div></div><button className="btn" disabled={isInstructor} title={isInstructor?"Instructor lens cannot start new conversations":"Create a local draft preview"} onClick={() => setModal("channel")}><Plus size={14}/> New conversation</button></div>
            <div className={`inbox-grid ${mobileThread ? "thread-open" : ""}`}>
              <div className="queue-col"><div className="queue-label">Saved queues</div>{["Needs reply", "Assigned to me", "All conversations", "Scheduled", "Opt-out / review"].map((q, i) => <button key={q} onClick={() => { setQueue(q); setMobileThread(false); }} className={`queue-item ${queue === q ? "selected" : ""}`}><span>{[<Inbox size={13}/>, <UserRound size={13}/>, <MessageCircle size={13}/>, <CalendarClock size={13}/>, <ShieldCheck size={13}/>][i]}</span>{q}<span className="queue-num">{queueCounts[i]}</span></button>)}
                <div className="queue-extra"><div className="queue-label">Channel phase</div><div style={{padding:"0 8px",display:"grid",gap:7}}><span className="tag green">SMS · proposed connector</span><span className="tag neutral"><Mail size={10}/> Email · later</span><span className="tag neutral">Calling · later</span></div>
                <div className="notice blue" style={{marginTop:16,fontSize:9}}><ShieldCheck size={14}/>Threads never cross locations. Switching location resets the active thread.</div></div>
              </div>
              <div className="thread-list">
                <div className="thread-search"><label className="sr-only" htmlFor="thread-search">Search conversations by adult, athlete or message</label><div style={{position:"relative"}}><Search size={13} style={{position:"absolute",left:9,top:9,color:"#989184"}}/><input id="thread-search" className="input" value={threadSearch} onChange={e => setThreadSearch(e.target.value)} placeholder="Search adult, athlete, message…" style={{paddingLeft:28}}/></div></div>
                <div className="thread-scroll">{visibleThreads.length ? visibleThreads.map(t => <button key={t.id} className={`thread-row ${activeThreadId === t.id ? "active" : ""}`} onClick={() => chooseThread(t.id)} aria-label={`Open thread with ${t.adult}, athlete ${t.athlete}`}>
                  <div className={`avatar ${t.id % 3 === 0 ? "rose" : t.id % 2 ? "" : "blue"}`}>{t.initials}</div><div className="thread-meta"><div className="thread-top"><span>{t.adult}</span><span className="muted">{t.time}</span></div><div className="thread-preview">{t.preview}</div><div className="thread-sub"><span>{t.athlete}</span><span>·</span><span>{t.assigned}</span>{t.unread && <span className="status-dot" aria-label="Unread"/>}</div></div>
                </button>) : <div className="empty"><div className="empty-mark"><Search size={17}/></div><h3>No matching threads</h3><p className="muted small-text">Clear your search or choose another saved queue.</p><button className="btn small" onClick={() => {setThreadSearch("");setQueue("All conversations");}}>Show all here</button></div>}</div>
              </div>
              <div className="conversation">
                <div className="conversation-head"><div className="row"><button className="icon-btn mobile-only" aria-label="Back to conversations" onClick={() => setMobileThread(false)}><ArrowLeft size={14}/></button><div className={`avatar ${currentThread.id % 2 ? "" : "blue"}`}>{currentThread.initials}</div><div><div style={{fontWeight:700,fontSize:11}}>{currentThread.adult}</div><div className="small-text muted">{currentThread.athlete} · {location.split(" · ")[0]}</div></div></div><div className="row">{currentThread.id>0&&(currentThread.assigned==="You"?<span className="presence"><span className="status-dot"/>{teammateReviewing?"Teammate viewing":"No one else here"}</span>:<span className="small-text muted">Assigned · {currentThread.assigned}</span>)}<button className="icon-btn" title="Toggle family context" aria-label="Toggle family context" onClick={() => setShowContext(!showContext)}><PanelRight size={14}/></button><button className="icon-btn" title="More thread actions" aria-label="More thread actions" disabled={currentThread.id<0} onClick={() => setModal("thread-actions")}><MoreHorizontal size={15}/></button></div></div>
                {currentThread.id<0&&<div className="empty"><div className="empty-mark"><Inbox size={16}/></div><h3>No conversations at {location.split(" · ")[0]}</h3><p className="small-text muted">This location has no synthetic thread examples. Select another location or keep the draft unsent.</p></div>}
                {currentThread.id>0&&currentThread.consent !== "Eligible" && <div className={`notice ${currentThread.consent === "Opted out" ? "red" : "blue"}`} style={{margin:"8px 12px 0"}}><ShieldCheck size={14}/><div><strong>{currentThread.consent === "Opted out" ? "SMS opted out · sending blocked" : "Recipient needs review"}</strong><br/>{currentThread.consent === "Opted out" ? "No tag or workflow can override this suppression." : "Confirm the guardian and athlete before outward contact."}</div></div>}
                <div className="message-scroll"><div className="message-day">TODAY · LOCAL DEMO THREAD</div>
                  {currentThread.messages.map((m, i) => <div key={`${m.time}-${i}`} className={`bubble-row ${m.from.startsWith("You · ") ? "out" : ""}`}><div className={`bubble ${m.kind === "internal" ? "internal" : m.kind === "scheduled" ? "out" : m.from.startsWith("You · ") ? "out" : ""}`}><div className="bubble-label">{m.kind === "internal" ? "Private staff note · not sent" : m.kind === "scheduled" ? "Scheduled preview · unsent" : m.from}</div>{m.text}<div className="bubble-time">{m.time}</div></div></div>)}
                  {teammateReviewing && <div className="presence" style={{marginTop:12}}><span className="status-dot"/>A teammate is reviewing this thread. A stale-draft check runs before simulated send.</div>}
                </div>
                <div className="composer">
                   <div className="composer-tools"><div className="row"><button className={`btn small ${messageMode === "Reply" ? "gold" : ""}`} onClick={() => setMessageMode("Reply")}><MessageCircle size={12}/>Reply</button><button className={`btn small ${messageMode === "Internal note" ? "gold" : ""}`} onClick={() => setMessageMode("Internal note")}><LockKeyhole size={12}/>Internal note</button></div><div className="row"><button className="btn small" disabled={currentThread.id<0} onClick={insertTemplate}><FileText size={12}/>Template</button><button className="btn small" onClick={() => flash("SMS attachments are not enabled in this prototype. Attachment capability: unavailable.")}><Plus size={12}/>Attach</button></div></div>
                  {messageMode === "Reply" && <div className="notice blue" style={{padding:"6px 8px",marginBottom:7,fontSize:9}}><span><strong>To:</strong> {currentThread.adult} · {currentThread.phone} &nbsp; <strong>From:</strong> Clubhouse · {location.split(" · ")[0]} &nbsp; SMS</span></div>}
                  <textarea aria-label={messageMode === "Reply" ? "Outward message draft" : "Private internal note"} value={draft} onChange={e => setDraft(e.target.value)} placeholder={messageMode === "Reply" ? "Write a thoughtful reply…" : "Private note for your team only…"}/>
                  {messageMode === "Reply" && draft && <div className="small-text muted" style={{marginTop:4}}>Draft stays local · last saved just now · source review recommended</div>}
                   <div className="composer-actions"><div className="row"><button className="btn small ghost" disabled={currentThread.id<0} onClick={() => setModal("schedule")}><CalendarClock size={12}/>Schedule preview</button><span className="small-text muted">SMS · no read receipts</span></div>
                    <div className="row">{messageMode === "Internal note" ? <button className="btn primary small" onClick={addInternalNote} disabled={currentThread.id<0}><LockKeyhole size={12}/>Add private note</button> : <button className="btn primary small" onClick={() => sendMessage(false)} disabled={!eligibleToSend}><Send size={12}/>Simulate send</button>}</div>
                  </div>
                  {!eligibleToSend && <div className="small-text" style={{color:"var(--red)",marginTop:6}}>Outbound reply blocked by consent or demo role. Draft remains local.</div>}
                </div>
              </div>
              {showContext && currentThread.id>0 && <aside className="context-col">
                <div className="context-title"><h3>Family context</h3><button className="btn small" onClick={() => go("Contacts")}>Open profile <ArrowUpRight size={11}/></button></div>
                <div className="row"><div className="avatar">{currentThread.initials}</div><div><strong>{currentThread.adult}</strong><div className="small-text muted">Adult recipient · {currentThread.phone}</div></div></div>
                <div className="context-block"><div className="eyebrow">Authorized conversation</div><div className="context-kv"><span>Guardian</span><strong>{currentThread.adult}</strong></div><div className="context-kv"><span>Athlete</span><strong>{currentThread.athlete}</strong></div><div className="context-kv"><span>Location</span><strong>{location.split(" · ")[0]}</strong></div><div className="context-kv"><span>SMS consent</span><span className={`tag ${classForStatus(currentThread.consent)}`}>{currentThread.consent}</span></div><div className="context-kv"><span>Assignment</span><select className="select" aria-label="Assign thread" value={currentThread.assigned} onChange={e => assignThread(e.target.value)} style={{padding:"4px 5px",fontSize:9}}>{["You","Devon","Leah","Unassigned"].map(x=><option key={x}>{x}</option>)}</select></div></div>
                <div className="context-block"><div className="between"><span className="eyebrow">Record tags</span><button className="icon-btn" aria-label="Add a tag" onClick={() => {setTagEntity("family");setModal("thread-tag");}}><Plus size={12}/></button></div>
                  {(["family","adult","athlete"] as const).map(entity=><div key={entity} style={{marginTop:7}}><div className="eyebrow">{entity==="family"?"Family":entity==="adult"?"Adult · "+currentThread.adult:"Athlete · "+currentThread.athlete}</div><div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:4}}>{[...(entity==="family"?currentThread.tags:[]),...(entityTags[currentThread.id]?.[entity]||[])].map((t,i)=><button key={`${t}-${i}`} className="tag" onClick={()=>{if(entity==="family"){setThreads(prev=>prev.map(x=>x.id===currentThread.id?{...x,tags:x.tags.filter(a=>a!==t)}:x));setFamilyRecords(prev=>prev.map(f=>f.adult===currentThread.adult&&f.location===location.split(" · ")[0]?{...f,tags:f.tags.filter(a=>a!==t)}:f));}else setEntityTags(prev=>({...prev,[currentThread.id]:{family:prev[currentThread.id]?.family||[],adult:prev[currentThread.id]?.adult||[],athlete:prev[currentThread.id]?.athlete||[],[entity]:(prev[currentThread.id]?.[entity]||[]).filter(a=>a!==t)}}));}} title={`Remove ${entity} tag`}>{t} <X size={9}/></button>)}{!currentThread.tags.length&&!entityTags[currentThread.id]?.[entity]?.length&&<span className="small-text muted">None</span>}</div><button className="btn small" style={{marginTop:4}} onClick={()=>{setTagEntity(entity);setModal("thread-tag");}}><Plus size={10}/>Add {entity} tag</button></div>)}
                  <div className="small-text muted" style={{marginTop:6}}>Entity scopes never cascade. Tags organize records; they are not consent.</div></div>
                <div className="context-block"><div className="eyebrow">AI thread brief <Sparkles size={11}/></div><p style={{fontSize:9,margin:"7px 0"}}>{currentThread.adult} asked about {currentThread.athlete}’s next visit. Review thread history and assigned staff context before confirming details. No pricing or availability promise is supported yet.</p><div className="small-text muted">Sources: inbound message · latest staff note<br/>Updated 9:47 AM · {aiState}</div><div className="row" style={{marginTop:8}}><button className="btn small" onClick={() => {setAiState("Unavailable · manual thread remains available");flash("AI unavailable state shown. Continue manually.");}}>Refresh brief</button><button className="btn small" onClick={() => {setDraft(`Hi ${currentThread.adult.split(" ")[0]}, I’m checking with the team about ${currentThread.athlete.split(" ")[0]}’s next visit and will confirm shortly.`);setMessageMode("Reply");}}>Use editable draft</button></div></div>
                 <div className="context-block"><div className="eyebrow">Related work</div><button className="btn small" disabled={!currentThreadDeal} style={{width:"100%",justifyContent:"flex-start",marginTop:7}} onClick={()=>{if(currentThreadDeal){setSelectedDeal(currentThreadDeal);go("Opportunities");}}}><Layers3 size={12}/>{currentThreadDeal?.name||"No linked opportunity at this location"}</button><button className="btn small" style={{width:"100%",justifyContent:"flex-start",marginTop:6}} onClick={()=>setModal("task")}><ClipboardList size={12}/>Create internal follow-up</button><button className="btn small" disabled={currentThread.assigned!=="You"} style={{width:"100%",justifyContent:"flex-start",marginTop:6}} onClick={()=>{setTeammateComposing(!teammateComposing);flash("Demo teammate presence updated.");}}>{teammateReviewing?"Pause teammate indicator":"Show teammate composing"}</button></div>
              </aside>}
            </div>
          </section>}
          {view === "Contacts" && <ContactsView families={visibleFamilies} role={role} search={contactSearch} setSearch={setContactSearch} status={contactStatus} setStatus={setContactStatus} selectedTags={contactTags} toggleTag={(t:string)=>setContactTags(p=>p.includes(t)?p.filter(x=>x!==t):[...p,t])} tags={tagLibrary} addTag={addTagToFamily} bulkSelected={bulkSelected} selectedIds={bulkSelection} onToggleBulk={(adult:string)=>setBulkSelection(prev=>prev.includes(adult)?prev.filter(x=>x!==adult):[...prev,adult])} onSelectVisible={()=>setBulkSelection(prev=>visibleFamilies.every(f=>prev.includes(f.adult))?prev.filter(x=>!visibleFamilies.some(f=>f.adult===x)):[...new Set([...prev,...visibleFamilies.map(f=>f.adult)])])} onClearBulk={()=>setBulkSelection([])} onBulk={()=>setModal("bulk")} onProfile={(f:any)=>{setSelectedFamily(f);setModal("profile");}} onCreate={()=>setModal("create-family")} onDuplicates={()=>setModal("duplicate-review")} flash={flash}/>}
          {view === "Opportunities" && <OpportunitiesView stages={stageNames} setStages={setStageNames} deals={visibleDeals} setDeals={setDealRecords} selected={selectedDeal} setSelected={setSelectedDeal} setStage={setDealStage} dealStage={dealStage} role={role} location={location} setModal={setModal} flash={flash}/>}
          {view === "Workflows" && <WorkflowsView tab={flowTab} setTab={setFlowTab} nodes={flowNodes} setNodes={setFlowNodes} selectedNode={selectedNode} setSelected={setSelectedNode} addNode={addFlowNode} catalog={CATALOG} paused={workflowPaused} setPaused={setWorkflowPaused} pauseScope={pauseScope} setPauseScope={setPauseScope} name={workflowName} setName={setWorkflowName} reentry={workflowReentry} setReentry={setWorkflowReentry} recurrence={workflowRecurrence} setRecurrence={setWorkflowRecurrence} relativeTiming={workflowRelativeTiming} setRelativeTiming={setWorkflowRelativeTiming} location={location} role={role} smsConfigured={!!smsConnections[location]} hasEligibleAdult={allowedLocationThreads.some(t=>t.consent==="Eligible")} sharing={workflowSharing[location]||"pending"} setSharing={(v:string)=>setWorkflowSharing(prev=>({...prev,[location]:v}))} validation={workflowValidation} modal={setModal} flash={flash}/>}
          {view === "Templates" && <TemplatesView body={templateBody} setBody={setTemplateBody} note={templateNote} setNote={setTemplateNote} location={location} previewAdult={currentThread.id>0?currentThread.adult.split(" ")[0]:""} previewAthlete={currentThread.id>0?currentThread.athlete.split(" ")[0]:""} sharing={workflowSharing[location]||"pending"} setSharing={(v:string)=>setWorkflowSharing(prev=>({...prev,[location]:v}))} modal={setModal} flash={flash} canUse={currentThread.id>0} useTemplate={()=>{if(currentThread.id<0){flash("No authorized conversation exists at this location.");return;}setDraft(templateBody.replaceAll("North Loop",location.split(" · ")[0]).replace("{{guardian_first}}",currentThread.adult.split(" ")[0]).replace("{{athlete_first}}",currentThread.athlete.split(" ")[0]));go("Conversations");flash("Template copied to the active local draft; inspect before any simulated send.");}}/>}
          {view === "Reports" && <ReportsView location={location}/>}
          {view === "Tags & Audiences" && <TagsView tags={tagLibrary} setTags={setTagLibrary} archivedTags={archivedTags} onRename={renameTag} onArchive={archiveTag} onRestore={restoreTag} families={locationFamilies} location={location} role={role} audienceLocation={audienceLocation} setAudienceLocation={setAudienceLocation} membership={audienceMembership} setMembership={setAudienceMembership} audienceRule={audienceRule} setRule={setAudienceRule} audienceTags={audienceSelectedTags} setAudienceTags={setAudienceSelectedTags} audienceLogic={audienceLogic} setLogic={setAudienceLogic} onPreview={(p:any)=>{setAudiencePreview(p);setModal("audience-preview");}} flash={flash}/>}
          {view === "Settings" && <SettingsView tab={settingsTab} setTab={setSettingsTab} location={location} role={role} smsConnected={!!smsConnections[location]} queuedCount={queuedSampleCount} queuedHeld={!!heldQueuedByLocation[location]} onSmsConnect={()=>setSmsConnections(prev=>({...prev,[location]:true}))} onSmsDisconnect={()=>{setSmsConnections(prev=>({...prev,[location]:false}));setHeldQueuedByLocation(prev=>({...prev,[location]:queuedSampleCount>0}));}} onReleaseQueued={()=>setHeldQueuedByLocation(prev=>({...prev,[location]:false}))} gmailConnected={!!gmailConnections[location]} onGmailConnect={()=>setGmailConnections(prev=>({...prev,[location]:true}))} onGmailDisconnect={()=>setGmailConnections(prev=>({...prev,[location]:false}))} flash={flash}/>}
          {view === "Exception review" && <ExceptionsView index={exception} setIndex={setException} flash={flash} role={role} location={location}/>}
          </>}
        </div>
      </main>
    </div>
    {mobileMenuOpen && <div className="mobile-route-menu" role="menu" aria-label="All CRM sections">{NAV.map(({name,icon:Icon})=><button role="menuitem" key={name} onClick={()=>{go(name);setMobileMenuOpen(false);}}><Icon size={14}/>{name}</button>)}</div>}
    <nav className="mobile-nav" aria-label="Main navigation">{[NAV[1],NAV[0],NAV[2],NAV[3],NAV[4]].map(({name,icon:Icon})=><button key={name} className={view===name?"active":""} onClick={()=>go(name)}><Icon size={16}/>{name === "Conversations" ? "Inbox" : name === "Opportunities" ? "Deals" : name}</button>)}<button className={mobileMenuOpen?"active":""} aria-expanded={mobileMenuOpen} aria-haspopup="menu" onClick={()=>setMobileMenuOpen(!mobileMenuOpen)}><MoreHorizontal size={17}/>More</button></nav>
    {modal && <Modal title={modal === "schedule" ? "Schedule preview" : modal === "stale" ? "Fresh review required" : modal === "channel" ? "New conversation · demo" : modal === "bulk" ? "Review bulk tag change" : modal === "profile" ? "Family profile · synthetic" : modal === "duplicate-review" ? "Duplicate suggestions · manual review" : modal === "create-family" ? "Create synthetic family" : modal === "thread-tag" ? "Add record tag" : modal === "publish" ? "Publish preview · current draft" : modal === "simulate" ? "Side-effect-free simulation" : modal === "role-boundary" ? "Demo permission boundary" : modal === "settings-connect" ? "Connector preview" : modal === "task" ? "Create internal follow-up" : modal === "thread-actions" ? "Thread actions" : modal === "advance" ? "Validate stage change" : modal === "required" ? "Complete required fields" : modal === "new-deal" ? "New opportunity · synthetic" : modal === "stages" ? "Pipeline stages" : modal === "deal-detail" ? "Opportunity detail" : modal === "deal-history" ? "Stage history" : modal === "ai-workflow" ? "AI workflow proposal" : modal === "pause-policy" ? "Pause scope" : modal === "audience-preview" ? "Eligible adult preview" : modal === "template-approval" ? "Template approval proposal" : "Review before continuing"} close={closeModal}>
      {modal === "schedule" && <div className="stack"><div className="notice"><CalendarClock size={15}/><span>Local preview only. Nothing is queued with a provider and no message will be delivered.</span></div><div className="field"><div className="eyebrow">Recipient</div><div className="input">{currentThread.adult} · {currentThread.phone}</div></div><div className="field"><div className="eyebrow">Sender</div><div className="input">Clubhouse · {location.split(" · ")[0]} · SMS</div></div><div className="field"><label htmlFor="schedule-time">Preview time</label><select id="schedule-time" className="select"><option>Tomorrow · 9:00 AM local time</option><option>Tomorrow · 10:30 AM local time</option></select></div><div className="field"><div className="eyebrow">Draft</div><div className="input">{draft || "Write a draft in the composer first."}</div></div><button className="btn primary" onClick={()=>{closeModal();sendMessage(true);}}>Save unsent schedule preview</button></div>}
      {modal === "stale" && <div className="stack"><div className="notice red"><AlertCircle size={15}/><span>Devon may have replied since this draft began. Your wording is preserved; nothing was sent.</span></div><div className="panel panel-pad"><div className="eyebrow">Preserved draft</div><p>{draft || savedDraft || "No draft text"}</p><div className="small-text muted">Compare latest messages, confirm owner and consent, then choose what to do.</div></div><div className="row"><button className="btn" onClick={()=>{setTeammateComposing(false);closeModal();flash("Thread refreshed. Draft preserved for your review.");}}>Refresh and review</button><button className="btn primary" onClick={()=>{setTeammateComposing(false);closeModal();sendMessage(false);}}>Review then simulate send</button></div></div>}
      {modal === "advance" && <div className="stack"><div className="notice"><CheckCircle2 size={15}/><span>Required information is present for this synthetic opportunity. Advancing only changes the local board.</span></div><div className="panel panel-pad"><div className="eyebrow">Opportunity · {location.split(" · ")[0]}</div><strong>{selectedDeal.name}</strong><p className="small-text">Family: {selectedDeal.family} · Owner: {selectedDeal.owner} · Next action: {selectedDeal.due}</p><div className="field"><label htmlFor="move-stage">Move to stage</label><select id="move-stage" className="select" value={dealStage||selectedDeal.stage} onChange={e=>setDealStage(e.target.value)}>{stageNames.map(s=><option key={s}>{s}</option>)}</select></div><div className="small-text muted" style={{marginTop:8}}>Stage history records who moved it and the reason. Sibling/program opportunities remain separate.</div></div><div className="between"><button className="btn" onClick={closeModal}>Cancel</button><button className="btn primary" onClick={()=>{const target=dealStage||stageNames[Math.min(stageNames.indexOf(selectedDeal.stage)+1,stageNames.length-1)];setDealRecords(prev=>prev.map(d=>d.name===selectedDeal.name?{...d,stage:target}:d));setSelectedDeal({...selectedDeal,stage:target});closeModal();flash(`Opportunity moved to ${target} in this local demo.`);}}>Confirm simulated stage change</button></div></div>}
      {modal === "required" && <div className="stack"><div className="notice red"><AlertCircle size={15}/><span>Stage advance is blocked until required details are complete.</span></div>{["Adult guardian","Athlete / program","Location","Owner","Next action"].map((x,i)=><label className="row small-text" key={x}><input type="checkbox" defaultChecked={i!==4}/> {x} confirmed</label>)}<div className="small-text muted">A real workflow would validate required fields before changing stage. This demo uses synthetic records only.</div><button className="btn" onClick={closeModal}>Return to opportunity</button></div>}
      {modal === "new-deal" && <div className="stack"><div className="notice blue"><Layers3 size={15}/><span>Create a distinct deal for a sibling or program. Existing family conversion history is preserved.</span></div><div className="field"><label htmlFor="deal-name">Opportunity name</label><input id="deal-name" className="input" defaultValue="Kai Brooks · Summer camp"/></div><div className="field"><label htmlFor="deal-family">Family / adult · {location.split(" · ")[0]}</label><select id="deal-family" className="select">{familyRecords.filter(f=>f.location===location.split(" · ")[0]).map(f=><option key={f.adult}>{f.adult}</option>)}</select></div><div className="row"><div className="field" style={{flex:1}}><label htmlFor="deal-stage">Stage</label><select id="deal-stage" className="select">{stageNames.map(s=><option key={s}>{s}</option>)}</select></div><div className="field" style={{flex:1}}><label htmlFor="deal-owner">Owner</label><select id="deal-owner" className="select"><option>You</option><option>Devon</option><option>Leah</option></select></div></div><div className="field"><label htmlFor="deal-next">Next action</label><input id="deal-next" className="input" defaultValue="Confirm camp dates with guardian"/></div>{!familyRecords.some(f=>f.location===location.split(" · ")[0])&&<div className="notice red"><AlertCircle size={14}/><span>No family record exists here. Create a synthetic family in Contacts first; no other location records can be selected.</span></div>}<button className="btn primary" disabled={!familyRecords.some(f=>f.location===location.split(" · ")[0])} onClick={()=>{const name=(document.getElementById("deal-name") as HTMLInputElement)?.value||"New synthetic opportunity";const family=(document.getElementById("deal-family") as HTMLSelectElement)?.value;const stage=(document.getElementById("deal-stage") as HTMLSelectElement)?.value||stageNames[0];const owner=(document.getElementById("deal-owner") as HTMLSelectElement)?.value||"You";const due=(document.getElementById("deal-next") as HTMLInputElement)?.value||"Needs next action";const created={name,family,stage,value:"$0",owner,due,tags:["New"]};setDealRecords(prev=>[...prev,created]);setSelectedDeal(created);closeModal();flash("Synthetic opportunity created in this local board.");}}>Create synthetic opportunity</button></div>}
      {modal === "stages" && <div className="stack"><div className="notice"><Settings2 size={15}/><span>Suggested stages are proposals pending leadership approval. Removal previews all affected synthetic deals across locations because the stage schema is shared.</span></div>{stageNames.map((s,i)=>{const count=dealRecords.filter(d=>d.stage===s).length;return <div className="panel panel-pad" key={s}><div className="between"><strong>{i+1}. {s}</strong><span className="tag neutral">{count} affected deals · all locations</span></div>{stageNames.length>2&&<div className="row" style={{marginTop:8,flexWrap:"wrap"}}><label className="eyebrow" htmlFor={`migration-${i}`}>Move existing records to</label><select id={`migration-${i}`} className="select" value={stageMigrations[s]||""} onChange={e=>setStageMigrations(prev=>({...prev,[s]:e.target.value}))}><option value="">Choose destination…</option>{stageNames.filter(x=>x!==s).map(x=><option key={x}>{x}</option>)}</select><button className="btn small danger" disabled={!stageMigrations[s]} onClick={()=>{const destination=stageMigrations[s];if(!stageNames.includes(destination)||destination===s){flash("Choose a valid destination stage first.");return;}if(window.confirm(`Preview: move ${count} deals from ${s} to ${destination}, then remove ${s}?`)){setDealRecords(prev=>prev.map(d=>d.stage===s?{...d,stage:destination}:d));if(selectedDeal.stage===s)setSelectedDeal({...selectedDeal,stage:destination});setStageNames((prev:string[])=>prev.filter(x=>x!==s));setStageMigrations(prev=>{const next={...prev};delete next[s];return next;});flash(`${count} deals migrated to ${destination} in the local demo.`);}}}>Confirm removal</button></div>}</div>})}<div className="row"><label className="eyebrow" htmlFor="stage-name-new">New stage</label><input className="input" id="stage-name-new" placeholder="Add a pipeline stage"/><button className="btn primary" onClick={()=>{const el=document.getElementById("stage-name-new") as HTMLInputElement;if(el.value.trim()&&!stageNames.includes(el.value.trim()))setStageNames([...stageNames,el.value.trim()]);else flash("Enter a new stage name that is not already listed.");}}>Add stage</button></div></div>}
      {modal === "deal-detail" && <div className="stack"><div className="panel panel-pad"><h2>{selectedDeal.name}</h2><div className="context-kv"><span>Family</span><strong>{selectedDeal.family}</strong></div><div className="context-kv"><span>Stage</span><strong>{selectedDeal.stage}</strong></div><div className="context-kv"><span>Owner</span><strong>{selectedDeal.owner}</strong></div><div className="context-kv"><span>Value</span><strong>{selectedDeal.value}</strong></div><div className="context-kv"><span>Next action</span><strong>{selectedDeal.due}</strong></div><hr className="divider"/><div className="eyebrow">Linked context</div><p className="small-text">{selectedDeal.family} · adult contact · related athlete remains a separate record. Stage update history is local demo state.</p></div><button className="btn primary" onClick={()=>{closeModal();setModal("advance");}}>Advance with validation</button></div>}
      {modal === "deal-history" && <div className="stack"><div className="panel panel-pad"><div className="eyebrow">Recent stage activity</div><p className="small-text">May 19 · {selectedDeal.owner} · {selectedDeal.stage}<br/>May 16 · Converted from evaluation inquiry<br/>May 12 · Opportunity created · {selectedDeal.family}</p><div className="small-text muted">Example history is synthetic and resets on refresh.</div></div><button className="btn" onClick={closeModal}>Close history</button></div>}
      {modal === "stages" ? null : null}
      {modal === "ai-workflow" && <div className="stack"><div className="notice blue"><Sparkles size={15}/><span>AI only drafts a proposed change. It never executes, sends or publishes.</span></div><div className="panel panel-pad"><strong>Assumptions</strong><p className="small-text">Adult guardian is the recipient; consent is verified at execution; one run per opportunity event; local timezone and quiet hours apply.</p><strong>Proposed diff</strong><p className="small-text">Add an eligibility condition before SMS; add staff-only task fallback; add booking goal exit.</p><strong>Unsupported nodes</strong><p className="small-text">Automatic price changes · guardian inference · global cross-location activation.</p></div><div className="row"><button className="btn" onClick={closeModal}>Discard proposal</button><button className="btn primary" onClick={()=>{setFlowNodes(prev=>prev.some(n=>n.kind==="goal exit")?prev:[...prev,{id:Date.now(),kind:"goal exit",title:"Goal · booking completed",detail:"AI draft proposal · review before approval"}]);closeModal();flash("AI-proposed goal node added to editable draft. Review and simulate; not published.");}}>Add proposal to draft</button></div></div>}
      {modal === "pause-policy" && <div className="stack"><div className="notice"><AlertCircle size={15}/><span>Pause scope is explicit. New entries and already queued sends are controlled separately.</span></div><label className="row small-text"><input type="radio" name="pause-policy" value="new entries" checked={pauseScope==="new entries"} onChange={()=>setPauseScope("new entries")}/> Block new entries only; preserve reviewed in-flight runs</label><label className="row small-text"><input type="radio" name="pause-policy" value="new entries and queued sends" checked={pauseScope==="new entries and queued sends"} onChange={()=>setPauseScope("new entries and queued sends")}/> Block new entries and hold queued sends for staff review</label><label className="row small-text"><input type="radio" name="pause-policy" value="resume" checked={pauseScope==="resume"} onChange={()=>setPauseScope("resume")}/> Resume new entries</label><div className="small-text muted">Selected scope: {pauseScope}</div><button className="btn primary" onClick={()=>{setWorkflowPaused(pauseScope!=="resume");closeModal();flash(`Workflow state saved locally: ${pauseScope}.`);}}>Apply selected pause scope</button></div>}
      {modal === "audience-preview" && <div className="stack"><div className="notice"><Users size={15}/><span>Current rule evaluation · eligible adults only · no send action exists in this prototype.</span></div><div className="panel panel-pad"><strong>Included · {audiencePreview.included.length} adults</strong><p className="small-text">{audiencePreview.included.length?audiencePreview.included.map((x:any)=><span key={x.adult}>{x.adult} · {x.location} · guardian of {x.athletes}<br/></span>):"No eligible adults match these rules."}</p><strong>Excluded · {audiencePreview.excluded.length} records</strong><p className="small-text">{audiencePreview.excluded.map((x:any)=><span key={x.adult}>{x.adult} · {x.reason}<br/></span>)}</p></div><div className="small-text muted">Rules are reevaluated at execution. Consent, sender, location and role remain separate gates; tags are not permission.</div><button className="btn primary" onClick={closeModal}>Close preview</button></div>}
      {modal === "create-family" && <div className="stack"><div className="notice blue"><Users size={15}/><span>Example record form. Changes are local and synthetic; no data import occurs.</span></div>{[["Adult guardian","adult-name"],["Athlete","athlete-name"]].map(([label,id])=><div className="field" key={id}><label htmlFor={id}>{label}</label><input id={id} className="input" placeholder={label==="Adult guardian"?"Enter synthetic adult name":"Enter linked athlete name"}/></div>)}<button className="btn primary" onClick={()=>{const adult=(document.getElementById("adult-name") as HTMLInputElement)?.value||"New adult";const athlete=(document.getElementById("athlete-name") as HTMLInputElement)?.value||"New athlete";const record={adult,athletes:athlete,location:location.split(" · ")[0],membership:"Lead",initials:initials(adult),tags:["New lead"],last:"Just now",status:"Active"};setFamilyRecords(prev=>[record,...prev]);closeModal();flash("Synthetic family record added locally. Refresh resets it.");}}>Save synthetic family</button></div>}
      {modal === "template-approval" && <div className="stack"><div className="notice blue"><FileText size={15}/><span>Versioned approval proposal. Existing local templates stay unchanged until approved.</span></div><div className="panel panel-pad"><strong>Version diff</strong><p className="small-text">{templateNote||"No proposal note entered."}<br/>Body changes are reviewed; unresolved variables block approval. Corporate template requires each location to accept or locally override.</p><div className="field"><label htmlFor="template-approver">Approver</label><select id="template-approver" className="select"><option>GM · proposal</option><option>Owner · demo</option></select></div></div><div className="row"><button className="btn" onClick={closeModal}>Cancel</button><button className="btn primary" onClick={()=>{closeModal();flash("Template version submitted as a local proposal. No location rollout occurred.");}}>Submit approval proposal</button></div></div>}
      {modal === "bulk" && <div className="stack"><div className="notice"><Users size={15}/><span>Preview: {bulkTargets.length} selected family record{bulkTargets.length===1?"":"s"} at {location.split(" · ")[0]}. No outreach or merge occurs.</span></div><div className="panel panel-pad"><strong>Will change</strong><p className="small-text">{bulkTargets.length?bulkTargets.map(f=><span key={f.adult}>{f.adult} · family · + {bulkTag}<br/></span>):"No selected families remain in this location."}<br/>Existing tags are preserved.</p><strong>Will not change</strong><p className="small-text muted">Athlete tags, adult consent, membership and records at other locations.</p></div><div className="field"><label htmlFor="bulk-tag">Family tag to add</label><select id="bulk-tag" className="select" value={bulkTag} onChange={e=>setBulkTag(e.target.value)}>{tagLibrary.map(t=><option key={t}>{t}</option>)}</select></div><div className="between"><button className="btn" onClick={()=>{setBulkSelection([]);closeModal();}}>Cancel</button><button className="btn primary" disabled={!bulkTargets.length} onClick={()=>{const selectedAdults=bulkTargets.map(f=>f.adult);setFamilyRecords(prev=>prev.map(f=>selectedAdults.includes(f.adult)&&f.location===location.split(" · ")[0]?{...f,tags:f.tags.includes(bulkTag)?f.tags:[...f.tags,bulkTag]}:f));setThreads(prev=>prev.map(t=>t.location===location&&selectedAdults.includes(t.adult)?{...t,tags:t.tags.includes(bulkTag)?t.tags:[...t.tags,bulkTag]}:t));setBulkSelection([]);closeModal();flash(`Added ${bulkTag} to ${bulkTargets.length} selected family records in ${location.split(" · ")[0]}.`);}}>Confirm simulated tag change</button></div></div>}
      {modal === "profile" && <div className="stack"><div className="row"><div className="avatar">{selectedFamily.initials}</div><div><h3>{selectedFamily.adult}</h3><span className="small-text muted">Adult · family · {selectedFamily.location}</span></div></div><div className="panel panel-pad"><div className="eyebrow">Linked athletes</div><p>{selectedFamily.athletes.split(" · ").map((a:string,i:number)=><span key={a}>{i>0&&" · "}<strong>{a}</strong></span>)}</p><div className="eyebrow">Conversion history</div><p className="small-text">{selectedFamily.membership==="Member"?"New lead → evaluation booked → member":"New lead → evaluation booked · May 12"}<br/>No automatic merging. Shared contact details are review suggestions only.</p><div className="eyebrow">Family tags</div><div className="row" style={{marginTop:5,flexWrap:"wrap"}}>{selectedFamily.tags.map((t:string)=><span className="tag" key={t}>{t}</span>)}</div></div><button className="btn" onClick={()=>{const match=threads.find(t=>t.adult===selectedFamily.adult&&t.location===location);closeModal();if(match){setActiveThreadId(match.id);go("Conversations");}else flash("No authorized conversation exists for this family in the current location.");}}>Open authorized thread</button></div>}
      {modal === "duplicate-review" && <div className="stack"><div className="notice"><Copy size={15}/><span>Suggestions are not merges. Similar phone/email may reflect shared guardians or legitimate household contact. Examples are scoped to {location.split(" · ")[0]}.</span></div>{duplicateSuggestions.length?duplicateSuggestions.map((x,i)=><div className="panel panel-pad" key={x[0]}><strong>{x[0]} ↔ {x[1]}</strong><div className="small-text muted">{x[2]}</div><div className="row" style={{marginTop:8}}><button className="btn small" onClick={()=>flash("Records kept separate. No merge performed.")}>Keep separate</button><button className="btn small" onClick={()=>flash("Flagged for manual identity review. No merge performed.")}>Flag for review</button></div></div>):<div className="empty"><div className="empty-mark"><Copy size={16}/></div><h3>No duplicate candidates here</h3><p className="small-text muted">No sample match suggestions are available at this location or within this role's assigned context.</p></div>}<button className="btn" onClick={closeModal}>Done</button></div>}
      {modal === "thread-tag" && <div className="stack"><div className="field"><label htmlFor="tag-entity-scope">Apply to entity</label><select id="tag-entity-scope" className="select" value={tagEntity} onChange={e=>setTagEntity(e.target.value as "family"|"adult"|"athlete")}><option value="family">Family · shared household context</option><option value="adult">Adult · {currentThread.adult}</option><option value="athlete">Athlete · {currentThread.athlete}</option></select></div>{tagLibrary.map(t=><button key={t} className="btn" onClick={()=>{if(tagEntity==="family"){setThreads(prev=>prev.map(x=>x.id===currentThread.id?{...x,tags:x.tags.includes(t)?x.tags:[...x.tags,t]}:x));setFamilyRecords(prev=>prev.map(f=>f.adult===currentThread.adult&&f.location===location.split(" · ")[0]?{...f,tags:f.tags.includes(t)?f.tags:[...f.tags,t]}:f));}else setEntityTags(prev=>{const curr=prev[currentThread.id]||{family:[],adult:[],athlete:[]};return {...prev,[currentThread.id]:{...curr,[tagEntity]:curr[tagEntity].includes(t)?curr[tagEntity]:[...curr[tagEntity],t]}};});closeModal();flash(`${t} added to the ${tagEntity} record only. No sibling inheritance.`);}}><Tag size={12}/>{t}</button>)}<div className="small-text muted">Tags do not imply consent or permission to send.</div></div>}
      {modal === "publish" && <div className="stack"><div className={`notice ${workflowValidation.length?"red":"blue"}`}><ShieldCheck size={15}/><span>Publish is simulated only. Location approver and in-flight run policy are required.</span></div><div className="panel panel-pad"><strong>Validation preview · {location.split(" · ")[0]}</strong><p className="small-text">{workflowValidation.length?workflowValidation.map((x:string)=><span key={x}>Blocked · {x}<br/></span>):"Ready for approval proposal. Execution still rechecks consent, sender, quiet hours, caps and appointment at send time."}</p><strong>Current node diff</strong><p className="small-text">{workflowDiff.length?workflowDiff.map((line:string)=><span key={line}>{line}<br/></span>):"No node-level changes detected."}</p><div className="field"><label htmlFor="publish-approver">Approver</label><select id="publish-approver" className="select"><option>GM · proposal</option><option>Owner · demo</option></select></div><div className="field" style={{marginTop:9}}><label htmlFor="publish-runs">Existing in-flight runs</label><select id="publish-runs" className="select"><option>Keep pinned to current version · recommended</option><option>Migrate after individual review</option><option>Hold queued sends for review</option></select></div></div><button className="btn primary" disabled={workflowValidation.length>0} onClick={()=>{closeModal();flash("Approval proposal saved locally; nothing was published live.");}}>Save approval proposal</button></div>}
      {modal === "simulate" && <div className="stack"><div className="notice blue"><Activity size={15}/><span>No actions execute. No tags change and no communication is sent.</span></div><div className="field"><label htmlFor="simulation-recipient">Authorized adult recipient · {location.split(" · ")[0]}</label><select id="simulation-recipient" className="select" value={simulationThread.id} onChange={e=>setSimulationRecipientId(Number(e.target.value))}>{allowedLocationThreads.map(t=><option key={t.id} value={t.id}>{t.adult} · {t.athlete}</option>)}</select></div><div className="panel panel-pad"><div className="eyebrow">Resolved route · {simulationThread.id>0?`${simulationThread.adult} / ${simulationThread.athlete}`:"No eligible recipient at this location"}</div><p>Location: {location.split(" · ")[0]} · timezone: local location timezone<br/>Sender: {smsConnections[location]?"demo sender enabled · simulated only":"not configured · SMS path blocked"}<br/>Recipient: {simulationThread.id>0?`${simulationThread.adult} · ${simulationThread.phone}`:"none"} · adult consent: {simulationThread.consent}<br/>Variables: {simulationThread.id>0?`${simulationThread.adult.split(" ")[0]} / ${simulationThread.athlete.split(" ")[0]} / ${location.split(" · ")[0]}`:"unresolved"}<br/>Re-entry: {workflowReentry} · {workflowRecurrence}<br/>Date anchor: {workflowRelativeTiming}<br/>Pause policy: {workflowPaused?`paused · ${pauseScope}`:"active in preview only"}</p><hr className="divider"/><div className="eyebrow">Current editable path</div>{flowNodes.map((node:FlowNode,i:number)=><div className="between small-text" key={node.id} style={{padding:"7px 0",borderTop:"1px solid var(--line)"}}><span><strong>{i+1}. {node.title}</strong><br/><span className="muted">{node.kind} · {node.timing||"next eligible local time"} · {node.detail}</span></span><span className={`tag ${node.kind==="SMS"&&(!smsConnections[location]||simulationThread.consent!=="Eligible")?"red":node.kind==="condition"?(simulationThread.consent==="Eligible"?"green":"red"):"neutral"}`}>{node.kind==="condition"?(simulationThread.consent==="Eligible"?"Eligible · yes branch":"No consent · staff review"):node.kind==="SMS"&&(!smsConnections[location]||simulationThread.consent!=="Eligible")?"Blocked · sender/recipient":node.kind==="goal exit"?"Exit when booking authoritative":node.kind==="trigger"&&workflowPaused?`Blocked · paused (${pauseScope})`:"Preview only"}</span></div>)}</div><button className="btn" onClick={closeModal}>Close simulation</button></div>}
      {modal === "role-boundary" && <div className="stack"><div className="notice"><LockKeyhole size={15}/><span>Role switch is a demo lens, not authentication. No permission check or identity claim is made.</span></div><p className="small-text">Owner and GM proposal can review this location’s synthetic records. Instructor view is assigned guardian context only, with billing hidden and direct athlete messages blocked. Corporate can propose versions; each location must explicitly accept or override.</p><button className="btn primary" onClick={closeModal}>Understood</button></div>}
      {modal === "settings-connect" && <div className="stack"><div className="notice blue"><LockKeyhole size={15}/><span>Preview only · no credentials requested, saved or transmitted.</span></div><div className="panel panel-pad"><h3>Location-scoped provider setup</h3><p className="small-text">Account ownership remains an open decision: independent location account or managed subaccount. Sender registration, local health, usage and offboarding require approval.</p><div className="field"><label>Demo action</label><select className="select"><option>Connect preview</option><option>Reconnect preview</option><option>Disconnect preview</option></select></div></div><button className="btn primary" onClick={()=>{closeModal();flash("Connector state changed in demo preview only.");}}>Confirm simulated action</button></div>}
      {modal === "task" && <div className="stack"><div className="notice"><ClipboardList size={15}/><span>Internal staff task only. No automatic parent outreach.</span></div><div className="field"><label htmlFor="task-title">Task</label><input id="task-title" className="input" defaultValue={`Check ${currentThread.athlete.split(" ")[0]} evaluation availability with the assigned coach`}/></div><div className="field"><label htmlFor="task-assignee">Assigned to</label><select id="task-assignee" className="select"><option>{currentThread.assigned==="Unassigned"?"You":currentThread.assigned}</option><option>You</option><option>Devon</option><option>Leah</option></select></div><button className="btn primary" onClick={()=>{closeModal();flash(`Internal follow-up task added locally for ${location.split(" · ")[0]}.`);}}>Create simulated task</button></div>}
      {modal === "thread-actions" && <div className="stack"><button className="btn" onClick={()=>{closeModal();setModal("task");}}><ClipboardList size={13}/>Create internal task</button><button className="btn" onClick={()=>{assignThread("Leah");closeModal();}}>Escalate to Leah</button><button className="btn" onClick={()=>{setTeammateComposing(false);closeModal();flash("Human takeover enabled; workflow pause shown for this thread.");}}>Take over · pause automation</button><button className="btn" onClick={()=>{closeModal();go("Exception review");}}>Review exception states</button></div>}
      {modal === "channel" && <div className="stack"><div className="notice red"><ShieldCheck size={15}/><span>SMS is a proposed phase. New conversation is a UI preview and does not send.</span></div><div className="field"><label htmlFor="new-thread-recipient">Adult recipient · {location.split(" · ")[0]}</label><select id="new-thread-recipient" className="select">{locationFamilies.map(f=><option key={f.adult}>{f.adult} · {f.athletes}</option>)}</select>{!locationFamilies.length&&<span className="small-text muted">No allowed synthetic family context exists here.</span>}</div><div className="field"><label htmlFor="new-thread-channel">Channel</label><select id="new-thread-channel" className="select"><option>SMS · simulated</option><option>Email · proposed and unconfigured</option></select></div><button className="btn primary" disabled={!locationFamilies.length||isInstructor} onClick={()=>{closeModal();flash("Synthetic conversation preview selected. No message sent.");}}>Open draft preview</button></div>}
      {modal === "settings-connect" ? null : null}
    </Modal>}
    {roleModal && <Modal title="Demo role boundary" close={()=>setRoleModal(false)}><div className="stack"><div className="notice"><LockKeyhole size={15}/><span>Role switch changes the prototype lens only. It does not authenticate or grant real access.</span></div><p className="small-text">{role.startsWith("Instructor") ? "Instructor lens: assigned guardian context only; billing hidden; direct athlete messaging blocked." : role.startsWith("Corporate") ? "Corporate lens: propose a version; locations must explicitly accept or locally override." : role.startsWith("GM") ? "GM lens: proposal controls are shown; final permissions remain pending leadership approval." : "Owner lens: synthetic local data only. Production permissions remain unapproved."}</p><button className="btn primary" onClick={()=>setRoleModal(false)}>Continue in demo</button></div></Modal>}
    {toast && <div className="toast" role="status">{toast}</div>}
  </div>;
}

export default CRMWorkbench;
